const getWamParameter=moduleId=>{const audioWorkletGlobalScope=globalThis;class WamParameter{constructor(info){this.info=info;this._value=info.defaultValue}set value(value){this._value=value}get value(){return this._value}set normalizedValue(valueNorm){this.value=this.info.denormalize(valueNorm)}get normalizedValue(){return this.info.normalize(this.value)}}if(audioWorkletGlobalScope.AudioWorkletProcessor){const ModuleScope=audioWorkletGlobalScope.webAudioModules.getModuleScope(moduleId);if(!ModuleScope.WamParameter)ModuleScope.WamParameter=WamParameter}return WamParameter};export default getWamParameter;